edits.text:
:root {
  color-scheme: light;
  --forest: #174a3b;
  --forest-deep: #10382e;
  --leaf: #dcebe3;
  --citrus: #d36d3d;
  --ink: #1d2b27;
  --muted: #64736d;
  --line: #d7dfdb;
  --paper: #f5f7f4;
  --white: #ffffff;
  --soft: #edf2ee;
  --danger: #a13e31;
  --font: "DM Sans", "Segoe UI", sans-serif;
  --mono: "IBM Plex Mono", ui-monospace, monospace;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.5;
}

button, input, select { font: inherit; }

.topbar {
  min-height: 62px;
  padding: 0 clamp(20px, 5vw, 72px);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  color: white;
  background: var(--forest-deep);
}

.wordmark {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: white;
  font-size: 12px;
  font-weight: 700;
  text-decoration: none;
}

.wordmark-mark {
  display: grid;
  width: 28px;
  aspect-ratio: 1;
  place-items: center;
  border: 1px solid #91b6a4;
  border-radius: 50%;
  color: #d5e8dc;
  font-family: var(--mono);
  font-size: 14px;
}

.runtime { display: flex; align-items: center; gap: 8px; color: #d4e2db; font-size: 12px; }
.runtime-dot { width: 8px; aspect-ratio: 1; border-radius: 50%; background: #e0a55c; }
.runtime-dot.ready { background: #73c89a; }
.runtime-dot.error { background: #ed8b72; }

main { max-width: 1280px; margin: 0 auto; padding: 42px clamp(20px, 5vw, 72px) 72px; }

.intro { max-width: 790px; margin-bottom: 30px; }
.eyebrow { margin: 0 0 8px; color: var(--citrus); font: 500 11px/1.3 var(--mono); letter-spacing: 0.08em; }
h1, h2, h3, p { margin-top: 0; }
h1 { max-width: 700px; margin-bottom: 10px; color: var(--forest-deep); font-size: clamp(32px, 4vw, 48px); line-height: 1.08; font-weight: 600; }
.intro-copy { max-width: 630px; margin-bottom: 20px; color: #53635c; font-size: 16px; }
.year-note { display: flex; align-items: flex-start; gap: 10px; max-width: 760px; padding: 12px 14px; border-left: 3px solid var(--citrus); background: #f4e9e1; color: #58463c; }
.year-note p { margin: 0; font-size: 12px; }
.note-mark { display: grid; flex: 0 0 17px; width: 17px; aspect-ratio: 1; place-items: center; border: 1px solid #9a5d40; border-radius: 50%; color: #9a5d40; font: 600 11px var(--mono); }

.workspace { display: grid; grid-template-columns: minmax(0, 1fr) minmax(330px, 0.9fr); align-items: start; gap: clamp(28px, 4vw, 56px); }
form { min-width: 0; }
.form-heading, .results-heading { display: flex; align-items: end; justify-content: space-between; gap: 16px; margin-bottom: 8px; }
.form-heading h2, .results-heading h2 { margin: 0; color: var(--forest-deep); font-size: 24px; font-weight: 600; }
.quiet-button { padding: 8px 11px; border: 1px solid #aebdb4; border-radius: 4px; background: transparent; color: var(--forest); font-size: 12px; font-weight: 600; cursor: pointer; }
.quiet-button:hover { background: var(--leaf); }

fieldset { min-width: 0; margin: 22px 0 0; padding: 18px 0 21px; border: 0; border-top: 1px solid var(--line); }
legend { padding: 0 12px 0 0; color: var(--ink); font-size: 16px; font-weight: 700; }
.step { margin-right: 8px; color: var(--citrus); font: 500 12px var(--mono); }
.section-help { max-width: 620px; margin: 5px 0 16px; color: var(--muted); font-size: 12px; }
.field-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px 16px; }
.field { display: grid; min-width: 0; gap: 6px; color: #34443d; font-size: 12px; font-weight: 600; }
.field b { color: var(--citrus); }
.field small { display: block; color: #76827d; font-size: 10px; font-weight: 400; }
.field-wide { grid-column: 1 / -1; }
.money-input, select { min-width: 0; height: 40px; border: 1px solid #cbd5cf; border-radius: 4px; background: var(--white); }
.money-input { display: flex; align-items: center; gap: 7px; padding: 0 10px; }
.money-input > span { color: #76827d; font: 12px var(--mono); }
.money-input:focus-within, select:focus { border-color: var(--forest); outline: 2px solid #bad5c6; outline-offset: 1px; }
.money-input input { width: 100%; min-width: 0; height: 100%; border: 0; outline: 0; background: transparent; color: var(--ink); font: 13px var(--mono); }
input[type="number"]::-webkit-inner-spin-button, input[type="number"]::-webkit-outer-spin-button { margin: 0; }
input[type="number"] { appearance: textfield; }
select { padding: 0 10px; color: var(--ink); font-size: 13px; }
.check-row { display: flex; align-items: flex-start; gap: 9px; color: #53635c; font-size: 12px; }
.check-row input { width: 16px; height: 16px; margin: 1px 0 0; accent-color: var(--forest); }
fieldset > .check-row { margin-top: 15px; }
.check-grid { display: grid; gap: 10px; margin-top: 15px; }
.form-actions { padding-top: 3px; }
.primary-button { display: flex; width: 100%; min-height: 48px; align-items: center; justify-content: space-between; padding: 0 16px; border: 0; border-radius: 4px; background: var(--forest); color: white; font-weight: 700; cursor: pointer; }
.primary-button:hover:not(:disabled) { background: #22624e; }
.primary-button:disabled { cursor: wait; opacity: 0.55; }
.primary-button span:last-child { font: 20px var(--mono); }
.form-error { min-height: 18px; margin: 7px 0 0; color: var(--danger); font-size: 12px; }

.results { position: sticky; top: 20px; min-width: 0; padding-top: 2px; }
.results-heading { display: block; margin-bottom: 18px; }
.results-heading .section-help { margin-bottom: 0; }
.regime-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.regime-card { min-width: 0; padding: 15px; border: 1px solid var(--line); border-top: 4px solid var(--forest); background: var(--white); }
.regime-card.old { border-top-color: var(--citrus); }
.regime-name { margin: 0 0 12px; color: var(--muted); font: 500 11px var(--mono); text-transform: uppercase; }
.monthly-label { margin-bottom: 2px; color: var(--muted); font-size: 11px; }
.monthly-value { margin: 0 0 14px; color: var(--forest-deep); font: 600 clamp(21px, 2.2vw, 29px)/1.2 var(--mono); overflow-wrap: anywhere; }
.result-list { margin: 0; }
.result-row { display: flex; justify-content: space-between; gap: 8px; padding: 7px 0; border-top: 1px solid #e8ede9; font-size: 11px; }
.result-row dt { color: var(--muted); }
.result-row dd { margin: 0; color: var(--ink); font: 500 11px var(--mono); text-align: right; }
.tax-note { min-height: 30px; margin: 9px 0 0; color: var(--muted); font-size: 10px; }

.sweep-section { margin-top: 28px; padding-top: 20px; border-top: 1px solid var(--line); }
.sweep-heading { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.sweep-heading h3 { margin: 0; color: var(--forest-deep); font-size: 19px; font-weight: 600; }
.sweep-tag { padding: 5px 7px; background: var(--leaf); color: var(--forest); font-size: 10px; font-weight: 600; white-space: nowrap; }
.table-scroll { overflow-x: auto; }
.sweep-table { width: 100%; margin-top: 12px; border-collapse: collapse; font-size: 10px; white-space: nowrap; }
.sweep-table caption { padding: 11px 0 6px; color: var(--forest); font: 500 10px var(--mono); text-align: left; text-transform: uppercase; }
.sweep-table th, .sweep-table td { padding: 7px 6px; border-bottom: 1px solid var(--line); text-align: right; }
.sweep-table th:first-child, .sweep-table td:first-child { text-align: left; }
.sweep-table th { color: var(--muted); font-weight: 600; }
.sweep-table td { font-family: var(--mono); }
.result-caveat { margin: 15px 0 0; color: var(--muted); font-size: 10px; }
.site-footer { display: flex; justify-content: space-between; gap: 16px; padding: 17px clamp(20px, 5vw, 72px); border-top: 1px solid var(--line); color: var(--muted); font: 10px var(--mono); }

[hidden] { display: none !important; }

@media (max-width: 900px) {
  .workspace { grid-template-columns: minmax(0, 1fr); }
  .results { position: static; }
  .regime-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 560px) {
  .topbar { min-height: 56px; padding-inline: 16px; }
  .runtime { max-width: 150px; font-size: 10px; }
  main { padding: 30px 16px 48px; }
  h1 { font-size: 34px; }
  .intro-copy { font-size: 14px; }
  .form-heading { align-items: center; }
  .form-heading h2, .results-heading h2 { font-size: 21px; }
  .field-grid { gap: 12px 10px; }
  .field-grid .field { font-size: 11px; }
  .regime-grid { gap: 8px; }
  .regime-card { padding: 11px 9px; }
  .monthly-value { font-size: 20px; }
  .result-row { font-size: 10px; }
  .result-row dd { font-size: 10px; }
  .site-footer { flex-direction: column; padding: 15px 16px; }
}

const form = document.querySelector("#salary-form");
const calculateButton = document.querySelector("#calculate-button");
const runtimeStatus = document.querySelector("#runtime-status");
const runtimeDot = document.querySelector("#runtime-dot");
const formError = document.querySelector("#form-error");
const results = document.querySelector("#results");
const currency = new Intl.NumberFormat("en-IN", {
  style: "currency",
  currency: "INR",
  maximumFractionDigits: 0,
});

let pyodide;

function setRuntimeState(message, state) {
  runtimeStatus.textContent = message;
  runtimeDot.className = `runtime-dot ${state}`;
}

function amount(value) {
  return currency.format(value || 0);
}

function appendResultRow(list, label, value) {
  const row = document.createElement("div");
  row.className = "result-row";
  const term = document.createElement("dt");
  term.textContent = label;
  const description = document.createElement("dd");
  description.textContent = value;
  row.append(term, description);
  list.append(row);
}

function renderRegime(name, data) {
  const card = document.createElement("article");
  card.className = `regime-card ${name.toLowerCase()}`;
  const title = document.createElement("p");
  title.className = "regime-name";
  title.textContent = `${name} regime`;
  const monthlyLabel = document.createElement("p");
  monthlyLabel.className = "monthly-label";
  monthlyLabel.textContent = "Estimated bank in-hand / month";
  const monthly = document.createElement("p");
  monthly.className = "monthly-value";
  monthly.textContent = amount(data.monthly_in_hand);
  const details = document.createElement("dl");
  details.className = "result-list";
  appendResultRow(details, "Annual in-hand", amount(data.bank_in_hand));
  appendResultRow(details, "Taxable salary", amount(data.taxable_salary));
  appendResultRow(details, "Income tax + cess", amount(data.income_tax));
  appendResultRow(details, "Retirement wealth", amount(data.employee_wealth));
  appendResultRow(details, "Government incl. PT", amount(data.government));
  appendResultRow(details, "Employer costs", amount(data.employer_costs));
  const note = document.createElement("p");
  note.className = "tax-note";
  note.textContent = data.tax_note;
  card.append(title, monthlyLabel, monthly, details, note);
  return card;
}

function appendTable(container, caption, headings, rows) {
  const table = document.createElement("table");
  table.className = "sweep-table";
  const tableCaption = document.createElement("caption");
  tableCaption.textContent = caption;
  const thead = document.createElement("thead");
  const headerRow = document.createElement("tr");
  for (const heading of headings) {
    const th = document.createElement("th");
    th.scope = "col";
    th.textContent = heading;
    headerRow.append(th);
  }
  thead.append(headerRow);
  const tbody = document.createElement("tbody");
  for (const row of rows) {
    const tr = document.createElement("tr");
    for (const value of row) {
      const td = document.createElement("td");
      td.textContent = value;
      tr.append(td);
    }
    tbody.append(tr);
  }
  table.append(tableCaption, thead, tbody);
  container.append(table);
}

function renderSweep(sweep) {
  const container = document.querySelector("#sweep-tables");
  container.replaceChildren();
  for (const regime of ["NEW", "OLD"]) {
    const rows = sweep[regime];
    appendTable(
      container,
      `${regime} regime · income and take-home`,
      ["Hike", "CTC / year", "Tax / year", "In-hand / month", "Monthly gain"],
      rows.map((row) => [
        `${row.hike}%`,
        amount(row.ctc),
        amount(row.income_tax),
        amount(row.monthly_in_hand),
        amount(row.monthly_gain),
      ]),
    );
    appendTable(
      container,
      `${regime} regime · CTC destinations`,
      ["Hike", "Retirement wealth", "Government", "Employer costs", "Unallocated"],
      rows.map((row) => [
        `${row.hike}%`,
        amount(row.employee_wealth),
        amount(row.government),
        amount(row.employer_costs),
        amount(row.unallocated_ctc),
      ]),
    );
  }
}

function collectInputs() {
  const payload = {};
  for (const element of form.elements) {
    if (!element.name) continue;
    if (element.type === "checkbox") {
      payload[element.name] = element.checked;
    } else if (element.type === "number") {
      payload[element.name] = Number(element.value || 0);
    } else {
      payload[element.name] = element.value;
    }
  }
  return payload;
}

function renderResults(output) {
  const cards = document.querySelector("#regime-results");
  cards.replaceChildren(renderRegime("NEW", output.new), renderRegime("OLD", output.old));
  renderSweep(output.sweep);
  document.querySelector("#result-summary").textContent =
    `CTC ${amount(output.new.ctc)} · CTC-flow reconciliation ${output.new.ctc_flow_total === output.new.ctc ? "matches" : "check components"}.`;
  results.hidden = false;
}

form.addEventListener("submit", async (event) => {
  event.preventDefault();
  formError.textContent = "";
  if (!form.reportValidity()) return;
  if (!pyodide) {
    formError.textContent = "The Python runtime is still loading. Please wait a moment and try again.";
    return;
  }

  const payload = collectInputs();
  if (payload.hra_qualifying_commission > payload.commission) {
    formError.textContent = "HRA-qualifying commission is a subset and cannot exceed annual commission.";
    return;
  }
  if (payload.employer_nps_deduction > payload.employer_nps) {
    formError.textContent = "The employer NPS deduction cannot exceed the employer NPS contribution.";
    return;
  }

  calculateButton.disabled = true;
  calculateButton.querySelector("span:first-child").textContent = "Calculating…";
  try {
    pyodide.globals.set("_salary_payload", JSON.stringify(payload));
    const resultProxy = await pyodide.runPythonAsync(
      "web_calculator.calculate_json(_salary_payload)",
    );
    const output = JSON.parse(resultProxy.toString());
    resultProxy.destroy();
    renderResults(output);
  } catch (error) {
    formError.textContent = `Could not calculate: ${error.message}`;
  } finally {
    calculateButton.disabled = false;
    calculateButton.querySelector("span:first-child").textContent = "Calculate take-home";
  }
});

document.querySelector("#load-example").addEventListener("click", () => {
  const example = {
    ctc: 1250000,
    basic: 437500,
    hra: 391083,
    other_taxable_allowances: 385417,
    employer_pf: 36000,
  };
  for (const [name, value] of Object.entries(example)) {
    form.elements.namedItem(name).value = value;
  }
  form.elements.namedItem("ctc").focus();
});

async function startPython() {
  try {
    setRuntimeState("Loading Python engine…", "");
    pyodide = await loadPyodide();
    for (const filename of ["indian_salary_ctc_estimator.py", "web_calculator.py"]) {
      const response = await fetch(filename);
      if (!response.ok) throw new Error(`Could not load ${filename} (${response.status})`);
      pyodide.FS.writeFile(`/home/pyodide/${filename}`, await response.text());
    }
    await pyodide.runPythonAsync(
      'import sys; sys.path.insert(0, "/home/pyodide"); import web_calculator',
    );
    calculateButton.disabled = false;
    setRuntimeState("Python ready · calculations stay in this browser", "ready");
  } catch (error) {
    setRuntimeState("Python runtime unavailable", "error");
    formError.textContent = `Could not start the Python engine: ${error.message}. Check your connection and reload.`;
  }
}

startPython();

"""JSON adapter used by the static Pyodide web page."""

import json

from indian_salary_ctc_estimator import SalaryInput, analyze, scale_compensation


def calculate(payload: dict) -> dict:
    data = SalaryInput(**payload)
    results = {regime: analyze(data, regime) for regime in ("NEW", "OLD")}
    sweep = {"NEW": [], "OLD": []}

    for regime in ("NEW", "OLD"):
        baseline = results[regime]
        for hike in (0, 5, 10, 15, 20, 25):
            scenario = scale_compensation(data, 1 + hike / 100)
            result = analyze(scenario, regime)
            sweep[regime].append(
                {
                    "hike": hike,
                    "ctc": scenario.ctc,
                    "income_tax": result["income_tax"],
                    "monthly_in_hand": result["monthly_in_hand"],
                    "monthly_gain": result["monthly_in_hand"] - baseline["monthly_in_hand"],
                    "employee_wealth": result["employee_wealth"],
                    "government": result["government"],
                    "employer_costs": result["employer_costs"],
                    "unallocated_ctc": result["unallocated_ctc"],
                }
            )

    return {
        "new": results["NEW"],
        "old": results["OLD"],
        "sweep": sweep,
    }


def calculate_json(payload_json: str) -> str:
    return json.dumps(calculate(json.loads(payload_json)))

